package com.docedit.sdk.presentation.preview

import android.net.Uri
import androidx.compose.foundation.ExperimentalFoundationApi
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.clickable

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyRow
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.pager.HorizontalPager
import androidx.compose.foundation.pager.rememberPagerState
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.draw.clipToBounds
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.graphicsLayer
import androidx.compose.ui.unit.dp
import coil.compose.AsyncImage
import com.docedit.sdk.data.model.DocumentPage
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.input.pointer.pointerInput
import com.docedit.sdk.presentation.common.ZoomablePage
import com.docedit.sdk.utils.Colors

/**
 * The screen shown immediately after scanning. Nothing here is destructive except
 * explicit Delete — Edit hands off to the full EditorScreen.
 */
@OptIn(ExperimentalMaterial3Api::class, ExperimentalFoundationApi::class)
@Composable
fun PreviewScreen(
    pages: List<DocumentPage>,
    onEditPage: (DocumentPage) -> Unit,
    onDeletePage: (DocumentPage) -> Unit,
    onRotatePage: (DocumentPage) -> Unit,
    onReorder: (from: Int, to: Int) -> Unit,
    onAddPage: () -> Unit,
    onExportPdf: () -> Unit,
    onExportImages: () -> Unit,
    onPreviewPdf: () -> Unit,
    onShare: () -> Unit,
    onSave: () -> Unit,
    onClose: () -> Unit
) {
    var selectedIndex by remember { mutableIntStateOf(0) }
    val safeIndex = selectedIndex.coerceIn(0, (pages.size - 1).coerceAtLeast(0))
    val currentPage = pages.getOrNull(safeIndex)


    var currentScale by remember { mutableFloatStateOf(1f) }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(if (pages.isNotEmpty()) "Page ${safeIndex + 1} of ${pages.size}" else "Document") },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = Colors.NavyBlue,
                    titleContentColor = Color.White,
                    navigationIconContentColor = Color.White,
                    actionIconContentColor = Color.White
                ),
                navigationIcon = {
                    IconButton(onClick = onClose) {
                        Icon(Icons.Default.Close, contentDescription = "Close")
                    }
                },
                actions = {
                    IconButton(onClick = { currentPage?.let(onRotatePage) }) {
                        Icon(Icons.Default.RotateRight, contentDescription = "Rotate")
                    }
                    IconButton(onClick = { currentPage?.let(onDeletePage) }) {
                        Icon(Icons.Default.Delete, contentDescription = "Delete page", tint = Colors.Maroon)
                    }
                }
            )
        },
        bottomBar = {
            BottomAppBar(
                containerColor = Colors.NavyBlue,
                contentColor = Color.White
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp),
                    horizontalArrangement = Arrangement.SpaceEvenly,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    ActionButton(Icons.Default.Edit, "Edit") { currentPage?.let(onEditPage) }
                    ActionButton(Icons.Default.AddAPhoto, "Add") { onAddPage() }
                    ActionButton(Icons.Default.PictureAsPdf, "PDF") { onExportPdf() }
                    ActionButton(Icons.Default.Visibility, "View") { onPreviewPdf() }
                    ActionButton(Icons.Default.Image, "Images") { onExportImages() }
                    ActionButton(Icons.Default.Share, "Share") { onShare() }
                    ActionButton(Icons.Default.Save, "Save") { onSave() }
                }
            }
        }
    ) { padding ->
        Column(modifier = Modifier.padding(padding).fillMaxSize()) {
            // Full page preview with swipe + pinch-to-zoom
            val pagerState = rememberPagerState(
                initialPage = safeIndex,
                pageCount = { pages.size }
            )

// Two-way sync: thumbnail tap -> pager
            LaunchedEffect(safeIndex) {
                if (pagerState.currentPage != safeIndex) {
                    pagerState.animateScrollToPage(safeIndex)
                }
            }
// pager swipe -> selectedIndex (updates title + thumbnail highlight)
            LaunchedEffect(pagerState.currentPage) {
                if (pagerState.currentPage != selectedIndex) {
                    selectedIndex = pagerState.currentPage
                }
            }

            Box(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxWidth()
                    .background(Color(0xFF111111)),
                contentAlignment = Alignment.Center
            ) {
                if (pages.isEmpty()) {
                    Text("No pages", color = Color.White)
                } else {
                    HorizontalPager(
                        state = pagerState,
                        modifier = Modifier.fillMaxSize(),
                        userScrollEnabled = currentScale <= 1f   // only allow page swipe when not zoomed
                    ) { pageIndex ->
                        ZoomablePage(
                            uri = pages[pageIndex].activeUri,
                            onScaleChange = { currentScale = it }
                        )
                    }
                }
            }

            // Thumbnail strip with reorder-by-tap-to-select (drag reorder wired via
            // org.burnoutcrew.composereorderable in the full implementation)
            LazyRow(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.surfaceVariant)
                    .padding(8.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                items(pages, key = { it.id }) { page ->
                    val index = pages.indexOf(page)
                    Box(
                        modifier = Modifier
                            .size(56.dp, 72.dp)
                            .clip(RoundedCornerShape(6.dp))
                            .clickable { selectedIndex = index }
                            .border(
                                width = if (index == safeIndex) 2.dp else 0.dp,
                                color = MaterialTheme.colorScheme.primary,
                                shape = RoundedCornerShape(6.dp)
                            )
                    ) {
                        AsyncImage(
                            model = page.activeUri,
                            contentDescription = "Page ${index + 1} thumbnail",
                            modifier = Modifier
                                .fillMaxSize()
                                .clip(RoundedCornerShape(6.dp))
                        )
                        Text(
                            text = "${index + 1}",
                            color = Color.White,
                            modifier = Modifier
                                .align(Alignment.BottomEnd)
                                .background(Color(0x88000000))
                                .padding(horizontal = 3.dp)
                        )
                    }
                }
            }
        }
    }

    // Keep selectedIndex valid if pages shrink (e.g. after delete)
    LaunchedEffect(pages.size) {
        if (safeIndex != selectedIndex) selectedIndex = safeIndex
    }
}

@Composable
private fun ActionButton(icon: androidx.compose.ui.graphics.vector.ImageVector, label: String, onClick: () -> Unit) {
    Column(horizontalAlignment = Alignment.CenterHorizontally) {
        IconButton(onClick = onClick) { Icon(icon, contentDescription = label) }
        Text(label, style = MaterialTheme.typography.labelSmall)
    }
}

package com.docedit.sdk.presentation.preview

import android.net.Uri
import androidx.compose.foundation.ExperimentalFoundationApi
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.clickable

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyRow
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.pager.HorizontalPager
import androidx.compose.foundation.pager.rememberPagerState
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.draw.clipToBounds
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.graphicsLayer
import androidx.compose.ui.unit.dp
import coil.compose.AsyncImage
import com.docedit.sdk.data.model.DocumentPage
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.input.pointer.pointerInput
import com.docedit.sdk.presentation.common.ZoomablePage
import com.docedit.sdk.utils.Colors

/**
 * The screen shown immediately after scanning. Nothing here is destructive except
 * explicit Delete — Edit hands off to the full EditorScreen.
 */
@OptIn(ExperimentalMaterial3Api::class, ExperimentalFoundationApi::class)
@Composable
fun PreviewScreen(
    pages: List<DocumentPage>,
    onEditPage: (DocumentPage) -> Unit,
    onDeletePage: (DocumentPage) -> Unit,
    onRotatePage: (DocumentPage) -> Unit,
    onReorder: (from: Int, to: Int) -> Unit,
    onAddPage: () -> Unit,
    onExportPdf: () -> Unit,
    onExportImages: () -> Unit,
    onPreviewPdf: () -> Unit,
    onShare: () -> Unit,
    onSave: () -> Unit,
    onClose: () -> Unit
) {
    var selectedIndex by remember { mutableIntStateOf(0) }
    val safeIndex = selectedIndex.coerceIn(0, (pages.size - 1).coerceAtLeast(0))
    val currentPage = pages.getOrNull(safeIndex)


    var currentScale by remember { mutableFloatStateOf(1f) }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(if (pages.isNotEmpty()) "Page ${safeIndex + 1} of ${pages.size}" else "Document") },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = Colors.NavyBlue,
                    titleContentColor = Color.White,
                    navigationIconContentColor = Color.White,
                    actionIconContentColor = Color.White
                ),
                navigationIcon = {
                    IconButton(onClick = onClose) {
                        Icon(Icons.Default.Close, contentDescription = "Close")
                    }
                },
                actions = {
                    IconButton(onClick = { currentPage?.let(onRotatePage) }) {
                        Icon(Icons.Default.RotateRight, contentDescription = "Rotate")
                    }
                    IconButton(onClick = { currentPage?.let(onDeletePage) }) {
                        Icon(Icons.Default.Delete, contentDescription = "Delete page", tint = Colors.Maroon)
                    }
                }
            )
        },
        bottomBar = {
            BottomAppBar(
                containerColor = Colors.NavyBlue,
                contentColor = Color.White
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp),
                    horizontalArrangement = Arrangement.SpaceEvenly,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    ActionButton(Icons.Default.Edit, "Edit") { currentPage?.let(onEditPage) }
                    ActionButton(Icons.Default.AddAPhoto, "Add") { onAddPage() }
                    ActionButton(Icons.Default.PictureAsPdf, "PDF") { onExportPdf() }
                    ActionButton(Icons.Default.Visibility, "View") { onPreviewPdf() }
                    ActionButton(Icons.Default.Image, "Images") { onExportImages() }
                    ActionButton(Icons.Default.Share, "Share") { onShare() }
                    ActionButton(Icons.Default.Save, "Save") { onSave() }
                }
            }
        }
    ) { padding ->
        Column(modifier = Modifier.padding(padding).fillMaxSize()) {
            // Full page preview with swipe + pinch-to-zoom
            val pagerState = rememberPagerState(
                initialPage = safeIndex,
                pageCount = { pages.size }
            )

// Two-way sync: thumbnail tap -> pager
            LaunchedEffect(safeIndex) {
                if (pagerState.currentPage != safeIndex) {
                    pagerState.animateScrollToPage(safeIndex)
                }
            }
// pager swipe -> selectedIndex (updates title + thumbnail highlight)
            LaunchedEffect(pagerState.currentPage) {
                if (pagerState.currentPage != selectedIndex) {
                    selectedIndex = pagerState.currentPage
                }
            }

            Box(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxWidth()
                    .background(Color(0xFF111111)),
                contentAlignment = Alignment.Center
            ) {
                if (pages.isEmpty()) {
                    Text("No pages", color = Color.White)
                } else {
                    HorizontalPager(
                        state = pagerState,
                        modifier = Modifier.fillMaxSize(),
                        userScrollEnabled = currentScale <= 1f   // only allow page swipe when not zoomed
                    ) { pageIndex ->
                        ZoomablePage(
                            uri = pages[pageIndex].activeUri,
                            onScaleChange = { currentScale = it }
                        )
                    }
                }
            }

            // Thumbnail strip with reorder-by-tap-to-select (drag reorder wired via
            // org.burnoutcrew.composereorderable in the full implementation)
            LazyRow(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.surfaceVariant)
                    .padding(8.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                items(pages, key = { it.id }) { page ->
                    val index = pages.indexOf(page)
                    Box(
                        modifier = Modifier
                            .size(56.dp, 72.dp)
                            .clip(RoundedCornerShape(6.dp))
                            .clickable { selectedIndex = index }
                            .border(
                                width = if (index == safeIndex) 2.dp else 0.dp,
                                color = Colors.Maroon,
                                shape = RoundedCornerShape(6.dp)
                            )
                    ) {
                        AsyncImage(
                            model = page.activeUri,
                            contentDescription = "Page ${index + 1} thumbnail",
                            modifier = Modifier
                                .fillMaxSize()
                                .clip(RoundedCornerShape(6.dp))
                        )
                        Text(
                            text = "${index + 1}",
                            color = Color.White,
                            modifier = Modifier
                                .align(Alignment.BottomEnd)
                                .background(Color(0x88000000))
                                .padding(horizontal = 3.dp)
                        )
                    }
                }
            }
        }
    }

    // Keep selectedIndex valid if pages shrink (e.g. after delete)
    LaunchedEffect(pages.size) {
        if (safeIndex != selectedIndex) selectedIndex = safeIndex
    }
}

@Composable
private fun ActionButton(icon: androidx.compose.ui.graphics.vector.ImageVector, label: String, onClick: () -> Unit) {
    Column(horizontalAlignment = Alignment.CenterHorizontally) {
        IconButton(onClick = onClick) { Icon(icon, contentDescription = label) }
        Text(label, style = MaterialTheme.typography.labelSmall)
    }
}

package com.docedit.sdk.presentation.preview

import android.app.Application
import android.content.ContentValues
import android.content.Context
import android.net.Uri
import android.os.Environment
import com.docedit.sdk.util.StoragePaths
import android.provider.MediaStore
import android.util.Log
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.docedit.sdk.data.model.DocumentPage
import com.docedit.sdk.data.repository.DocumentRepository
import com.docedit.sdk.image.BitmapUtils
import com.docedit.sdk.image.ImageProcessor
import com.docedit.sdk.pdf.PdfGenerator
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.File
import java.io.FileOutputStream

class PreviewViewModel(application: Application) : AndroidViewModel(application) {

    private val repository = DocumentRepository.getInstance(application)
    val pages: StateFlow<List<DocumentPage>> = repository.pages

    private val _isLoading = MutableStateFlow(false)
    val isLoading: StateFlow<Boolean> = _isLoading

    // Uri of a freshly-generated PDF being shown in the AndroidPdfViewer overlay (null = hidden).
    private val _pdfPreviewUri = MutableStateFlow<Uri?>(null)
    val pdfPreviewUri: StateFlow<Uri?> = _pdfPreviewUri

    private val _snackbarMessage = MutableStateFlow<String?>(null)
    val snackbarMessage: StateFlow<String?> = _snackbarMessage

    fun seed(images: List<Uri>) {
        _isLoading.value = true
        repository.seedFromImages(images)
        _isLoading.value = false
    }

    fun seedFromPdf(pdfUri: Uri) = viewModelScope.launch {
        _isLoading.value = true
        repository.seedFromPdf(pdfUri)
        _isLoading.value = false
    }

    fun addPages(newUris: List<Uri>) = repository.addPages(newUris)

    fun deletePage(pageId: String) = repository.deletePage(pageId)

    fun reorder(from: Int, to: Int) = repository.reorder(from, to)

    /** Quick rotate right from the Preview screen, no need to open the full Editor. */
    fun quickRotate(page: DocumentPage) = viewModelScope.launch(Dispatchers.Default) {
        val newRotation = (page.rotationDegrees + 90) % 360
        val bitmap = BitmapUtils.loadScaled(getApplication(), page.originalUri)
        val rotated = ImageProcessor.rotate(bitmap, newRotation)
        val destFile = repository.newEditedFile(page.id)
        val savedUri = BitmapUtils.savePng(rotated, destFile)
        repository.updatePage(page.copy(editedUri = savedUri, rotationDegrees = newRotation))
    }

    suspend fun exportPdf(): Uri? = withContext(Dispatchers.IO) {
        try {
            val dest = File(repository.cacheDir, "export_${System.currentTimeMillis()}.pdf")
            PdfGenerator.generate(getApplication(), pages.value, dest)
            Uri.fromFile(dest)
        } catch (e: Exception) {
            Log.e("PreviewViewModel", "exportPdf failed", e)
            null
        }
    }



    suspend fun exportToDownloads(): Uri? = withContext(Dispatchers.IO) {
        try {
            val resolver = getApplication<Application>().contentResolver
            val fileName = "DocMaster_${System.currentTimeMillis()}.pdf"

            val uri = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.Q) {
                val contentValues = ContentValues().apply {
                    put(MediaStore.MediaColumns.DISPLAY_NAME, fileName)
                    put(MediaStore.MediaColumns.MIME_TYPE, "application/pdf")
                    put(MediaStore.MediaColumns.RELATIVE_PATH, StoragePaths.downloadsRelativePath())
                }
                resolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, contentValues)
            } else {
                val downloadsDir = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS)
                val docMasterDir = File(downloadsDir, "DocMasterAi")
                if (!docMasterDir.exists()) docMasterDir.mkdirs()
                val destFile = File(docMasterDir, fileName)
                Uri.fromFile(destFile)
            }

            if (uri != null) {
                val outputStream = if (uri.scheme == "content") {
                    resolver.openOutputStream(uri)
                } else {
                    FileOutputStream(File(uri.path!!))
                }

                outputStream?.use { 
                    PdfGenerator.generate(getApplication(), pages.value, it, jpegQuality = 100)
                }
                _snackbarMessage.value = "Exported to: ${StoragePaths.downloadsUserVisiblePath(fileName)}"
                uri
            } else {
                null
            }
        } catch (e: Exception) {
            Log.e("PreviewViewModel", "exportToDownloads failed", e)
            null
        }
    }

    fun clearSnackbarMessage() {
        _snackbarMessage.value = null
    }

    /** Generates the PDF and opens it in the AndroidPdfViewer preview overlay. */
    fun previewPdf() = viewModelScope.launch {
        _pdfPreviewUri.value = exportPdf()
    }

    fun dismissPdfPreview() {
        _pdfPreviewUri.value = null
    }

    override fun onCleared() {
        super.onCleared()
        DocumentRepository.clear()
    }
}

