package com.ndroid.docmasterai

import android.app.Activity
import android.content.Context
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.provider.OpenableColumns
import android.util.Log
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.activity.result.IntentSenderRequest
import androidx.activity.result.contract.ActivityResultContracts
import androidx.activity.viewModels
import androidx.compose.animation.AnimatedVisibility
import androidx.compose.animation.slideInVertically
import androidx.compose.animation.slideOutVertically
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Scaffold
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.lifecycle.lifecycleScope
import androidx.navigation.NavDestination.Companion.hasRoute
import androidx.navigation.compose.currentBackStackEntryAsState
import androidx.navigation.compose.rememberNavController
import com.docedit.sdk.api.DocumentEditor
import com.google.mlkit.vision.documentscanner.GmsDocumentScanningResult
import com.ndroid.docmasterai.premium.PremiumManager
import com.ndroid.docmasterai.scanner.ScannerManager
import com.ndroid.docmasterai.ui.navigation.BottomNavBar
import com.ndroid.docmasterai.ui.navigation.DocMasterNavHost
import com.ndroid.docmasterai.ui.navigation.Screen
import com.ndroid.docmasterai.ui.theme.DocMasterTheme
import com.tom_roush.pdfbox.android.PDFBoxResourceLoader
import dagger.hilt.android.AndroidEntryPoint
import kotlinx.coroutines.launch
import java.io.File
import javax.inject.Inject
import kotlin.io.path.exists

@AndroidEntryPoint
class MainActivity : ComponentActivity() {

    @Inject
    lateinit var scannerManager: ScannerManager

    @Inject
    lateinit var premiumManager: PremiumManager

    private val mainViewModel: MainViewModel by viewModels()

    /** Which document is currently open in the editor, so its result can be saved back. */
    private var editingDocumentId: String? = null

//    initializing pdfbox here


    private val editorLauncher = DocumentEditor.registerLauncher(this) { result ->
        val docId = editingDocumentId
        editingDocumentId = null
        if (!result.wasCancelled) {
            if (docId != null) {
                mainViewModel.saveEditedDocument(docId, result)
            } else {
                // Opened from external intent, create a new document
                mainViewModel.createNewDocument(result)
            }
        }
    }

    private val scannerLauncher = registerForActivityResult(ActivityResultContracts.StartIntentSenderForResult()) { result ->
        if (result.resultCode == Activity.RESULT_OK) {
            val gmsResult = GmsDocumentScanningResult.fromActivityResultIntent(result.data)
            gmsResult?.let {
                lifecycleScope.launch {
                    scannerManager.onScanResult(it)
                }
            }
        }
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        handleIntent(intent)
    }

    private fun handleIntent(intent: Intent) {
        val action = intent.action
        val type = intent.type

        when (action) {
            Intent.ACTION_VIEW -> {
                intent.data?.let { launchEditor(it, type) }
            }
            Intent.ACTION_SEND -> {
                @Suppress("DEPRECATION")
                val uri = intent.getParcelableExtra<Uri>(Intent.EXTRA_STREAM)
                uri?.let { launchEditor(it, type) }
            }
            Intent.ACTION_SEND_MULTIPLE -> {
                @Suppress("DEPRECATION")
                val uris = intent.getParcelableArrayListExtra<Uri>(Intent.EXTRA_STREAM)
                if (!uris.isNullOrEmpty()) {
                    // For multiple files, we currently only support images
                    if (type?.startsWith("image/") == true) {
                        editorLauncher.launch(DocumentEditor.Input(images = uris))
                    } else {
                        // If it's PDFs, just open the first one for now
                        launchEditor(uris[0], type)
                    }
                }
            }
        }
    }

    private fun launchEditor(uri: Uri, type: String?) {
        // Ensure we have permission to read the URI
        try {
            applicationContext.contentResolver.takePersistableUriPermission(
                uri,
                Intent.FLAG_GRANT_READ_URI_PERMISSION
            )
        } catch (_: Exception) {
        }

        if (type?.startsWith("image/") == true) {
            editorLauncher.launch(DocumentEditor.Input(images = listOf(uri)))
        } else if (type == "application/pdf" || uri.toString().endsWith(".pdf", true)) {
            editorLauncher.launch(DocumentEditor.Input(pdf = uri))
        } else {
            if (uri.toString().endsWith(".pdf", true)) {
                editorLauncher.launch(DocumentEditor.Input(pdf = uri))
            } else {
                editorLauncher.launch(DocumentEditor.Input(images = listOf(uri)))
            }
        }
    }



    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        PDFBoxResourceLoader.init(this)

        handleIntent(intent)

        setContent {
            DocMasterTheme {
                DocMasterMainScreen(
                    onStartScan = { scannerManager.startScan(this, scannerLauncher) },
                    onItemClick = { documentId, images, pdf ->
                        editingDocumentId = documentId
                        val isPremium = premiumManager.isPremium.value || 
                            (premiumManager.trialStatus.value is com.ndroid.docmasterai.premium.TrialStatus.Active)

                        val config = com.docedit.sdk.api.EditorConfig(isPremium = isPremium)
                        editorLauncher.launch(DocumentEditor.Input(images = images, pdf = pdf, config = config))
                    }
                )
            }
        }
    }
}

@Composable
fun DocMasterMainScreen(onStartScan: () -> Unit,
                        onItemClick: (documentId: String, images: List<Uri>, pdf: Uri?) -> Unit) {
    val navController = rememberNavController()
    val navBackStackEntry by navController.currentBackStackEntryAsState()
    val currentDestination = navBackStackEntry?.destination

    // Show bottom bar only on main screens
    val showBottomBar = currentDestination?.let { dest ->
        listOf(
            Screen.Home::class,
            Screen.Scanner::class,
            Screen.PdfTools::class,
            Screen.FileManager::class,
            Screen.Settings::class,
        ).any { dest.hasRoute(it) }
    } ?: false

    Scaffold(
        modifier = Modifier.fillMaxSize(),
        bottomBar = {
            AnimatedVisibility(
                visible = showBottomBar,
                enter = slideInVertically(initialOffsetY = { it }),
                exit = slideOutVertically(targetOffsetY = { it }),
            ) {
                BottomNavBar(navController = navController, onScanClick = onStartScan)
            }
        }
    ) { innerPadding ->
        DocMasterNavHost(
            navController = navController,
            onStartScan = onStartScan,
            modifier = Modifier.padding(innerPadding),
            onItemClick = onItemClick
        )
    }
}

package com.ndroid.docmasterai

import android.app.Activity
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.widget.Toast
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.activity.result.contract.ActivityResultContracts
import androidx.activity.viewModels
import androidx.compose.animation.AnimatedVisibility
import androidx.compose.animation.slideInVertically
import androidx.compose.animation.slideOutVertically
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Scaffold
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.lifecycleScope
import androidx.lifecycle.repeatOnLifecycle
import androidx.navigation.NavDestination.Companion.hasRoute
import androidx.navigation.compose.currentBackStackEntryAsState
import androidx.navigation.compose.rememberNavController
import com.docedit.sdk.api.DocumentEditor
import com.google.mlkit.vision.documentscanner.GmsDocumentScanningResult
import com.ndroid.docmasterai.premium.PremiumManager
import com.ndroid.docmasterai.scanner.ScannerManager
import com.ndroid.docmasterai.ui.navigation.BottomNavBar
import com.ndroid.docmasterai.ui.navigation.DocMasterNavHost
import com.ndroid.docmasterai.ui.navigation.Screen
import com.ndroid.docmasterai.ui.theme.DocMasterTheme
import com.tom_roush.pdfbox.android.PDFBoxResourceLoader
import dagger.hilt.android.AndroidEntryPoint
import kotlinx.coroutines.launch
import javax.inject.Inject

@AndroidEntryPoint
class MainActivity : ComponentActivity() {

    @Inject
    lateinit var scannerManager: ScannerManager

    @Inject
    lateinit var premiumManager: PremiumManager

    private val mainViewModel: MainViewModel by viewModels()

    /** Which document is currently open in the editor, so its result can be saved back. */
    private var editingDocumentId: String? = null

//    initializing pdfbox here


    private val editorLauncher = DocumentEditor.registerLauncher(this) { result ->
        val docId = editingDocumentId
        editingDocumentId = null
        if (!result.wasCancelled) {
            if (docId != null) {
                mainViewModel.saveEditedDocument(docId, result)
            } else {
                // Opened from external intent, create a new document
                mainViewModel.createNewDocument(result)
            }
        }
    }

    private val scannerLauncher = registerForActivityResult(ActivityResultContracts.StartIntentSenderForResult()) { result ->
        if (result.resultCode == Activity.RESULT_OK) {
            val gmsResult = GmsDocumentScanningResult.fromActivityResultIntent(result.data)
            gmsResult?.let {
                lifecycleScope.launch {
                    scannerManager.onScanResult(it)
                }
            }
        }
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        handleIntent(intent)
    }

    override fun onSaveInstanceState(outState: Bundle) {
        outState.putString("editingDocumentId", editingDocumentId)
        super.onSaveInstanceState(outState)
    }

    private fun handleIntent(intent: Intent) {
        val action = intent.action
        val type = intent.type
        if (action == Intent.ACTION_VIEW || action == Intent.ACTION_SEND || action == Intent.ACTION_SEND_MULTIPLE) {
            editingDocumentId = null
        }
        
        when (action) {
            Intent.ACTION_VIEW -> {
                intent.data?.let { launchEditor(it, type) }
            }
            Intent.ACTION_SEND -> {
                @Suppress("DEPRECATION")
                val uri = intent.getParcelableExtra<Uri>(Intent.EXTRA_STREAM)
                uri?.let { launchEditor(it, type) }
            }
            Intent.ACTION_SEND_MULTIPLE -> {
                @Suppress("DEPRECATION")
                val uris = intent.getParcelableArrayListExtra<Uri>(Intent.EXTRA_STREAM)
                if (!uris.isNullOrEmpty()) {
                    // For multiple files, we currently only support images
                    if (type?.startsWith("image/") == true) {
                        editorLauncher.launch(DocumentEditor.Input(images = uris))
                    } else {
                        // If it's PDFs, just open the first one for now
                        launchEditor(uris[0], type)
                    }
                }
            }
        }
    }

    private fun launchEditor(uri: Uri, type: String?) {
        // Ensure we have permission to read the URI
        try {
            applicationContext.contentResolver.takePersistableUriPermission(
                uri,
                Intent.FLAG_GRANT_READ_URI_PERMISSION
            )
        } catch (_: Exception) {
        }

        if (type?.startsWith("image/") == true) {
            editorLauncher.launch(DocumentEditor.Input(images = listOf(uri)))
        } else if (type == "application/pdf" || uri.toString().endsWith(".pdf", true)) {
            editorLauncher.launch(DocumentEditor.Input(pdf = uri))
        } else {
            if (uri.toString().endsWith(".pdf", true)) {
                editorLauncher.launch(DocumentEditor.Input(pdf = uri))
            } else {
                editorLauncher.launch(DocumentEditor.Input(images = listOf(uri)))
            }
        }
    }



    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        editingDocumentId = savedInstanceState?.getString("editingDocumentId")
        enableEdgeToEdge()
        PDFBoxResourceLoader.init(this)

        lifecycleScope.launch {
            repeatOnLifecycle(Lifecycle.State.STARTED) {
                mainViewModel.messages.collect { message ->
                    Toast.makeText(this@MainActivity, message, Toast.LENGTH_LONG).show()
                }
            }
        }
        if (savedInstanceState == null) handleIntent(intent)

        setContent {
            DocMasterTheme {
                DocMasterMainScreen(
                    onStartScan = { scannerManager.startScan(this, scannerLauncher) },
                    onItemClick = { documentId, images, pdf ->
                        editingDocumentId = documentId
                        val isPremium = premiumManager.isPremium.value || 
                            (premiumManager.trialStatus.value is com.ndroid.docmasterai.premium.TrialStatus.Active)
                        
                        val config = com.docedit.sdk.api.EditorConfig(isPremium = isPremium)
                        editorLauncher.launch(DocumentEditor.Input(images = images, pdf = pdf, config = config))
                    }
                )
            }
        }
    }
}

@Composable
fun DocMasterMainScreen(onStartScan: () -> Unit,
                        onItemClick: (documentId: String, images: List<Uri>, pdf: Uri?) -> Unit) {
    val navController = rememberNavController()
    val navBackStackEntry by navController.currentBackStackEntryAsState()
    val currentDestination = navBackStackEntry?.destination

    // Show bottom bar only on main screens
    val showBottomBar = currentDestination?.let { dest ->
        listOf(
            Screen.Home::class,
            Screen.Scanner::class,
            Screen.PdfTools::class,
            Screen.FileManager::class,
            Screen.Settings::class,
        ).any { dest.hasRoute(it) }
    } ?: false

    Scaffold(
        modifier = Modifier.fillMaxSize(),
        bottomBar = {
            AnimatedVisibility(
                visible = showBottomBar,
                enter = slideInVertically(initialOffsetY = { it }),
                exit = slideOutVertically(targetOffsetY = { it }),
            ) {
                BottomNavBar(navController = navController, onScanClick = onStartScan)
            }
        }
    ) { innerPadding ->
        DocMasterNavHost(
            navController = navController,
            onStartScan = onStartScan,
            modifier = Modifier.padding(innerPadding),
            onItemClick = onItemClick
        )
    }
}

package com.ndroid.docmasterai

import android.content.Context
import android.net.Uri
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import androidx.room.withTransaction
import com.docedit.sdk.api.DocumentEditor
import com.ndroid.docmasterai.data.local.db.DocMasterDatabase
import com.ndroid.docmasterai.data.local.entity.DocumentEntity
import com.ndroid.docmasterai.data.local.entity.PageEntity
import com.ndroid.docmasterai.data.repository.DocumentRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.NonCancellable
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.receiveAsFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.File
import java.util.UUID
import javax.inject.Inject

@HiltViewModel
class MainViewModel @Inject constructor(
    @param:ApplicationContext private val context: Context,
    private val repository: DocumentRepository,
    private val database: DocMasterDatabase,
) : ViewModel() {
    private val messagesChannel = Channel<String>(Channel.BUFFERED)
    val messages = messagesChannel.receiveAsFlow()

    fun saveEditedDocument(documentId: String, result: DocumentEditor.Result) = persist(documentId, result)

    fun createNewDocument(result: DocumentEditor.Result) = persist(null, result)

    private fun persist(documentId: String?, result: DocumentEditor.Result) {
        if (result.wasCancelled) return
        viewModelScope.launch {
            try {
                withContext(Dispatchers.IO) { saveResult(documentId, result) }
                messagesChannel.send("Document saved")
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                messagesChannel.send("Could not save document: ${e.message ?: "Unknown error"}")
            }
        }
    }

    private suspend fun saveResult(documentId: String?, result: DocumentEditor.Result) {
        val pdf = requireNotNull(result.pdf) { "The editor returned no PDF." }
        require(result.pageCount > 0) { "The document has no pages." }
        require(result.images.isEmpty() || result.images.size == result.pageCount) { "Incomplete editor pages." }
        val id = documentId ?: UUID.randomUUID().toString()
        // A fresh directory ensures failed saves never overwrite the previous revision.
        val directory = File(context.filesDir, "documents/$id/${UUID.randomUUID()}")
        check(directory.mkdirs()) { "Cannot create document directory." }
        var committed = false
        try {
            val pdfFile = copyTo(pdf, File(directory, "document.pdf"))
            val pages = result.images.mapIndexed { index, uri ->
                PageEntity(
                    id = UUID.randomUUID().toString(),
                    documentId = id,
                    pageNumber = index,
                    imagePath = copyTo(uri, File(directory, "page_${index + 1}.png")).absolutePath,
                )
            }
            val thumbnail = result.thumbnail?.let { copyTo(it, File(directory, "thumbnail.png")).absolutePath }
                ?: pages.firstOrNull()?.imagePath

            // Commit and its cleanup marker must complete together, even if the host closes.
            withContext(NonCancellable) {
                database.withTransaction {
                    val existing = if (documentId != null) {
                        requireNotNull(repository.getDocumentById(documentId)) { "The document no longer exists." }
                    } else null
                    val document = existing?.copy(
                        filePath = pdfFile.absolutePath,
                        thumbnailPath = thumbnail,
                        fileType = "pdf",
                        fileSize = pdfFile.length(),
                        pageCount = result.pageCount,
                        updatedAt = System.currentTimeMillis(),
                    ) ?: DocumentEntity(
                        id = id,
                        title = "Document_${System.currentTimeMillis()}",
                        filePath = pdfFile.absolutePath,
                        thumbnailPath = thumbnail,
                        fileType = "pdf",
                        fileSize = pdfFile.length(),
                        pageCount = result.pageCount,
                        sourceType = "import",
                    )
                    if (existing == null) {
                        repository.saveDocument(document)
                    } else {
                        repository.updateDocument(document)
                        repository.addRecentAccess(id, "edit")
                    }
                    repository.replacePages(id, pages)
                }
                committed = true
            }
        } finally {
            if (!committed) directory.deleteRecursively()
        }
    }

    private fun copyTo(uri: Uri, destination: File): File {
        requireNotNull(context.contentResolver.openInputStream(uri)) { "Cannot read editor output." }.use { input ->
            destination.outputStream().use { output -> input.copyTo(output) }
        }
        check(destination.length() > 0L) { "The editor output is empty." }
        return destination
    }
}

package com.ndroid.docmasterai.data.repository

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.net.Uri
import android.graphics.pdf.PdfDocument
import android.graphics.pdf.PdfRenderer
import android.os.ParcelFileDescriptor
import com.docedit.sdk.ocr.OcrProcessor
import com.ndroid.docmasterai.data.remote.OpenAiService
import com.ndroid.docmasterai.data.local.dao.ConversionHistoryDao
import com.ndroid.docmasterai.data.local.entity.DocumentEntity
import com.ndroid.docmasterai.data.repository.DocumentRepository
import com.ndroid.docmasterai.data.local.entity.ConversionHistoryEntity
import com.ndroid.docmasterai.data.model.ConversionType
import com.ndroid.docmasterai.data.model.ResizeMode
import com.ndroid.docmasterai.data.model.ResizeOptions
import com.tom_roush.pdfbox.pdmodel.PDDocument
import com.tom_roush.pdfbox.text.PDFTextStripper
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.withContext
import java.io.File
import java.io.FileOutputStream
import java.util.UUID
import javax.inject.Inject
import javax.inject.Singleton
import org.opencv.android.Utils
import org.opencv.core.Mat
import org.opencv.core.Size
import org.opencv.imgproc.Imgproc
import android.os.Build
import java.io.FileWriter
import com.ndroid.docmasterai.util.StoragePaths
import android.content.ContentValues
import android.graphics.Color
import android.provider.MediaStore
import android.provider.OpenableColumns

@Singleton
class ConversionRepository @Inject constructor(
    @ApplicationContext private val context: Context,
    private val conversionHistoryDao: ConversionHistoryDao,
    private val documentRepository: DocumentRepository,
    private val openAiService: OpenAiService
) {
    private val outputDir: File
        get() = File(context.filesDir, "conversions").also { it.mkdirs() }

    fun getConversionHistory(): Flow<List<ConversionHistoryEntity>> =
        conversionHistoryDao.getConversionHistory()

    suspend fun convertPdfToImages(pdfPath: String): List<String> = withContext(Dispatchers.IO) {
        val images = mutableListOf<String>()
        val pdfUri = Uri.parse(pdfPath)
        val pfd = try {
            if (pdfUri.scheme == "content") {
                context.contentResolver.openFileDescriptor(pdfUri, "r")
            } else {
                ParcelFileDescriptor.open(File(pdfPath), ParcelFileDescriptor.MODE_READ_ONLY)
            }
        } catch (e: Exception) {
            null
        } ?: return@withContext emptyList()

        val pdfName = getFileName(pdfPath).substringBeforeLast(".")
        val renderer = PdfRenderer(pfd)
        for (i in 0 until renderer.pageCount) {
            val page = renderer.openPage(i)
            // Using higher scale for better quality
            val bitmap = Bitmap.createBitmap(page.width * 2, page.height * 2, Bitmap.Config.ARGB_8888)
            // Fill with white to avoid black background in JPEGs
            bitmap.eraseColor(Color.WHITE)
            page.render(bitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY)
            page.close()

            val fileName = "${pdfName}_page_${i + 1}.jpg"
            val tempFile = File(context.cacheDir, fileName)
            FileOutputStream(tempFile).use { out ->
                bitmap.compress(Bitmap.CompressFormat.JPEG, 95, out)
            }
            bitmap.recycle()

            val savedPath = saveToDownloads(tempFile, fileName, "image/jpeg", pdfName)
            images.add(savedPath)

            // Also save a copy internally for the document list
            val internalFile = File(outputDir, fileName)
            tempFile.copyTo(internalFile, overwrite = true)
            registerConvertedDocument(internalFile, "jpg", "PDF to Image")
        }
        renderer.close()
        pfd.close()

        saveConversionHistory(pdfPath, images.firstOrNull() ?: "", ConversionType.PDF_TO_IMAGE)
        images
    }

    suspend fun convertImageToPdf(imagePaths: List<String>, outputName: String): String =
        withContext(Dispatchers.IO) {
            val pdfDocument = PdfDocument()

            imagePaths.forEachIndexed { index, path ->
                val bitmap = decodeBitmapFromPath(path)
                    ?: throw IllegalArgumentException("Cannot decode image at $path")
                val pageInfo = PdfDocument.PageInfo.Builder(bitmap.width, bitmap.height, index + 1).create()
                val page = pdfDocument.startPage(pageInfo)
                page.canvas.drawBitmap(bitmap, 0f, 0f, null)
                pdfDocument.finishPage(page)
                bitmap.recycle()
            }

            val fileName = "${outputName}_${UUID.randomUUID()}.pdf"
            val tempFile = File(context.cacheDir, fileName)
            FileOutputStream(tempFile).use { out ->
                pdfDocument.writeTo(out)
            }
            pdfDocument.close()

            val savedPath = saveToDownloads(tempFile, fileName, "application/pdf")
            registerConvertedDocument(File(tempFile.absolutePath), "pdf", ConversionType.IMAGE_TO_PDF.displayName)
            saveConversionHistory(imagePaths.first(), savedPath, ConversionType.IMAGE_TO_PDF)
            savedPath
        }

    suspend fun convertImageFormat(
        imagePath: String,
        targetFormat: Bitmap.CompressFormat,
        quality: Int = 95
    ): String = withContext(Dispatchers.IO) {
        val bitmap = decodeBitmapFromPath(imagePath) ?: throw IllegalArgumentException("Cannot decode image at $imagePath")
        val ext = when (targetFormat) {
            Bitmap.CompressFormat.JPEG -> "jpg"
            Bitmap.CompressFormat.PNG -> "png"
            else -> "webp"
        }
        val fileName = "converted_${UUID.randomUUID()}.$ext"
        val tempFile = File(context.cacheDir, fileName)
        FileOutputStream(tempFile).use { out ->
            bitmap.compress(targetFormat, quality, out)
        }
        bitmap.recycle()

        val type = when (targetFormat) {
            Bitmap.CompressFormat.JPEG -> if (imagePath.endsWith(".png", true)) ConversionType.PNG_TO_JPG else ConversionType.WEBP_TO_JPG
            Bitmap.CompressFormat.PNG -> ConversionType.JPG_TO_PNG
            else -> ConversionType.PNG_TO_JPG
        }
        val mimeType = when (targetFormat) {
            Bitmap.CompressFormat.JPEG -> "image/jpeg"
            Bitmap.CompressFormat.PNG -> "image/png"
            else -> "image/webp"
        }
        val savedPath = saveToDownloads(tempFile, fileName, mimeType)
        registerConvertedDocument(File(tempFile.absolutePath), ext, type.displayName)
        saveConversionHistory(imagePath, savedPath, type)
        savedPath
    }

    suspend fun convertImageToText(imagePath: String): String = withContext(Dispatchers.IO) {
        val uri = try { Uri.parse(imagePath) } catch (e: Exception) { Uri.fromFile(File(imagePath)) }
        val rawText = OcrProcessor.extractText(context, uri)
        if (rawText.isBlank()){
            throw IllegalArgumentException("No text could be found in the selected image. Please try an image with clearer text.")
        }
        val enhancedText = openAiService.processPdfContent(rawText)

        val fileName = "ocr_${UUID.randomUUID()}.txt"
        val tempFile = File(context.cacheDir, fileName)
        FileWriter(tempFile).use { writer ->
            writer.write(enhancedText)
        }

        val savedPath = saveToDownloads(tempFile, fileName, "text/plain")

        // Use a persistent file in internal storage for the database to ensure it's always available
        val internalFile = File(outputDir, fileName)
        FileWriter(internalFile).use { it.write(enhancedText) }
        registerConvertedDocument(internalFile, "txt", ConversionType.IMAGE_TO_TEXT.displayName)

        saveConversionHistory(imagePath, savedPath, ConversionType.IMAGE_TO_TEXT)
        savedPath
    }

    suspend fun convertPdfToText(pdfPath: String): String = withContext(Dispatchers.IO) {
        val rawText = try {
            val uri = try { Uri.parse(pdfPath) } catch (e: Exception) { Uri.fromFile(File(pdfPath)) }
            val inputStream = if (uri.scheme == "content") {
                context.contentResolver.openInputStream(uri)
            } else {
                File(pdfPath).inputStream()
            }

            inputStream?.use { input ->
                PDDocument.load(input).use { document ->
                    PDFTextStripper().getText(document)
                }
            } ?: ""
        } catch (e: Exception) {
            ""
        }

        if (rawText.isBlank()) {
            throw IllegalArgumentException("No text could be extracted from this PDF. It might be an image-only PDF or scanned document without OCR.")
        }

        val processedText = openAiService.processPdfContent(rawText)

        val fileName = "pdf_text_${UUID.randomUUID()}.txt"
        val tempFile = File(context.cacheDir, fileName)
        FileWriter(tempFile).use { writer ->
            writer.write(processedText)
        }

        val savedPath = saveToDownloads(tempFile, fileName, "text/plain")

        val internalFile = File(outputDir, fileName)
        FileWriter(internalFile).use { it.write(processedText) }
        registerConvertedDocument(internalFile, "txt", ConversionType.PDF_TO_TEXT.displayName)

        saveConversionHistory(pdfPath, savedPath, ConversionType.PDF_TO_TEXT)
        savedPath
    }

    private suspend fun registerConvertedDocument(file: File, type: String, sourceType: String) {
        val documentEntity = DocumentEntity(
            id = UUID.randomUUID().toString(),
            title = file.name,
            filePath = file.absolutePath,
            thumbnailPath = null,
            fileType = type,
            fileSize = file.length(),
            pageCount = 1,
            sourceType = sourceType,
            createdAt = System.currentTimeMillis(),
            updatedAt = System.currentTimeMillis()
        )
        documentRepository.saveDocument(documentEntity)
    }

    private fun saveToDownloads(
        tempFile: File, 
        displayName: String, 
        mimeType: String,
        subFolder: String? = null
    ): String {
        val resolver = context.contentResolver
        val relativePath = if (subFolder != null) {
            "${StoragePaths.downloadsRelativePath()}/$subFolder"
        } else {
            StoragePaths.downloadsRelativePath()
        }

        val contentValues = ContentValues().apply {
            put(MediaStore.MediaColumns.DISPLAY_NAME, displayName)
            put(MediaStore.MediaColumns.MIME_TYPE, mimeType)
            put(MediaStore.MediaColumns.RELATIVE_PATH, relativePath)
        }

        val uri = resolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, contentValues)
        val finalPath = uri?.let {
            resolver.openOutputStream(it)?.use { output ->
                tempFile.inputStream().use { input ->
                    input.copyTo(output)
                }
            }
            if (subFolder != null) {
                "Download/${StoragePaths.DOWNLOAD_SUBDIR}/$subFolder/$displayName"
            } else {
                StoragePaths.downloadsUserVisiblePath(displayName)
            }
        } ?: tempFile.absolutePath

        return finalPath
    }

    private fun getFileName(path: String): String {
        val uri = Uri.parse(path)
        if (uri.scheme == "content") {
            context.contentResolver.query(uri, null, null, null, null)?.use { cursor ->
                val nameIndex = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME)
                if (cursor.moveToFirst()) {
                    return cursor.getString(nameIndex)
                }
            }
        }
        return File(path).name
    }

    suspend fun resizeImage(imagePath: String, options: ResizeOptions): String =
        withContext(Dispatchers.IO) {
            // Decode original bitmap (supports file paths and content URIs)
            val original = decodeBitmapFromPath(imagePath)
                ?: throw IllegalArgumentException("Cannot decode image at $imagePath")

            // Calculate desired dimensions
            val (newWidth, newHeight) = calculateDimensions(original, options)

            // Convert Bitmap -> Mat
            val srcMat = Mat()
            Utils.bitmapToMat(original, srcMat)

            // Resize using OpenCV
            val dstMat = Mat()
            Imgproc.resize(srcMat, dstMat, Size(newWidth.toDouble(), newHeight.toDouble()), 0.0, 0.0, Imgproc.INTER_AREA)

            // Convert Mat -> Bitmap
            val resized = Bitmap.createBitmap(newWidth, newHeight, Bitmap.Config.ARGB_8888)
            Utils.matToBitmap(dstMat, resized)

            // Determine output format and write file
            val webpFormat = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
                Bitmap.CompressFormat.WEBP_LOSSY
            } else {
                Bitmap.CompressFormat.WEBP
            }

            val format = when (options.outputFormat.lowercase()) {
                "png" -> Bitmap.CompressFormat.PNG
                "webp" -> webpFormat
                else -> Bitmap.CompressFormat.JPEG
            }

            val outputFile = File(outputDir, "resized_${UUID.randomUUID()}.${options.outputFormat}")
            FileOutputStream(outputFile).use { out ->
                resized.compress(format, options.quality, out)
            }

            // Release resources
            srcMat.release()
            dstMat.release()
            original.recycle()
            resized.recycle()

            registerConvertedDocument(outputFile, options.outputFormat, "Resize")
            outputFile.absolutePath
        }

    private fun decodeBitmapFromPath(path: String): Bitmap? {
        // If path points to an actual file, decode directly
        try {
            val file = File(path)
            if (file.exists()) return BitmapFactory.decodeFile(path)

            // Otherwise try treating the string as a Uri (content://... or file://...)
            val uri = try {
                Uri.parse(path)
            } catch (e: Exception) {
                null
            }

            if (uri != null && uri.scheme != null) {
                context.contentResolver.openInputStream(uri)?.use { stream ->
                    return BitmapFactory.decodeStream(stream)
                }
            }
        } catch (e: Exception) {
            // fallthrough to return null
        }
        return null
    }

    private fun calculateDimensions(bitmap: Bitmap, options: ResizeOptions): Pair<Int, Int> {
        return when (options.mode) {
            ResizeMode.WIDTH -> {
                val ratio = options.width.toFloat() / bitmap.width
                val height = if (options.maintainAspectRatio) (bitmap.height * ratio).toInt() else bitmap.height
                options.width to height
            }
            ResizeMode.HEIGHT -> {
                val ratio = options.height.toFloat() / bitmap.height
                val width = if (options.maintainAspectRatio) (bitmap.width * ratio).toInt() else bitmap.width
                width to options.height
            }
            ResizeMode.PERCENTAGE -> {
                val w = (bitmap.width * options.percentage / 100f).toInt()
                val h = (bitmap.height * options.percentage / 100f).toInt()
                w to h
            }
            ResizeMode.CUSTOM -> options.width to options.height
        }
    }

    private suspend fun saveConversionHistory(source: String, output: String, type: ConversionType) {
        conversionHistoryDao.insertConversion(
            ConversionHistoryEntity(
                id = UUID.randomUUID().toString(),
                sourceFile = source,
                outputFile = output,
                conversionType = type.name,
                fileSize = File(output).takeIf { it.exists() }?.length() ?: 0L,
            )
        )
    }
}

package com.ndroid.docmasterai.data.repository

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.net.Uri
import android.graphics.pdf.PdfDocument
import android.graphics.pdf.PdfRenderer
import android.os.ParcelFileDescriptor
import com.ndroid.docmasterai.data.remote.OpenAiService
import com.ndroid.docmasterai.data.local.dao.ConversionHistoryDao
import com.ndroid.docmasterai.data.local.entity.DocumentEntity
import com.ndroid.docmasterai.data.repository.DocumentRepository
import com.ndroid.docmasterai.data.local.entity.ConversionHistoryEntity
import com.ndroid.docmasterai.data.model.ConversionType
import com.ndroid.docmasterai.data.model.ResizeMode
import com.ndroid.docmasterai.data.model.ResizeOptions
import com.tom_roush.pdfbox.pdmodel.PDDocument
import com.tom_roush.pdfbox.text.PDFTextStripper
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.withContext
import java.io.File
import java.io.FileOutputStream
import java.util.UUID
import javax.inject.Inject
import javax.inject.Singleton
import org.opencv.android.Utils
import org.opencv.core.Mat
import org.opencv.core.Size
import org.opencv.imgproc.Imgproc
import android.os.Build
import java.io.FileWriter
import com.ndroid.docmasterai.util.StoragePaths
import android.content.ContentValues
import android.graphics.Color
import android.provider.MediaStore
import android.provider.OpenableColumns

@Singleton
class ConversionRepository @Inject constructor(
    @ApplicationContext private val context: Context,
    private val conversionHistoryDao: ConversionHistoryDao,
    private val documentRepository: DocumentRepository,
    private val openAiService: OpenAiService,
    private val ocrRepository: OcrRepository
) {
    private val outputDir: File
        get() = File(context.filesDir, "conversions").also { it.mkdirs() }

    fun getConversionHistory(): Flow<List<ConversionHistoryEntity>> =
        conversionHistoryDao.getConversionHistory()

    suspend fun convertPdfToImages(pdfPath: String): List<String> = withContext(Dispatchers.IO) {
        val images = mutableListOf<String>()
        val pdfUri = Uri.parse(pdfPath)
        val pfd = try {
            if (pdfUri.scheme == "content") {
                context.contentResolver.openFileDescriptor(pdfUri, "r")
            } else {
                ParcelFileDescriptor.open(File(pdfPath), ParcelFileDescriptor.MODE_READ_ONLY)
            }
        } catch (e: Exception) {
            null
        } ?: return@withContext emptyList()

        val pdfName = getFileName(pdfPath).substringBeforeLast(".")
        val renderer = PdfRenderer(pfd)
        for (i in 0 until renderer.pageCount) {
            val page = renderer.openPage(i)
            // Using higher scale for better quality
            val bitmap = Bitmap.createBitmap(page.width * 2, page.height * 2, Bitmap.Config.ARGB_8888)
            // Fill with white to avoid black background in JPEGs
            bitmap.eraseColor(Color.WHITE)
            page.render(bitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY)
            page.close()

            val fileName = "${pdfName}_page_${i + 1}.jpg"
            val tempFile = File(context.cacheDir, fileName)
            FileOutputStream(tempFile).use { out ->
                bitmap.compress(Bitmap.CompressFormat.JPEG, 95, out)
            }
            bitmap.recycle()

            val savedPath = saveToDownloads(tempFile, fileName, "image/jpeg", pdfName)
            images.add(savedPath)
            
            // Also save a copy internally for the document list
            val internalFile = File(outputDir, fileName)
            tempFile.copyTo(internalFile, overwrite = true)
            registerConvertedDocument(internalFile, "jpg", "PDF to Image")
        }
        renderer.close()
        pfd.close()

        saveConversionHistory(pdfPath, images.firstOrNull() ?: "", ConversionType.PDF_TO_IMAGE)
        images
    }

    suspend fun convertImageToPdf(imagePaths: List<String>, outputName: String): String =
        withContext(Dispatchers.IO) {
            val pdfDocument = PdfDocument()

            imagePaths.forEachIndexed { index, path ->
                val bitmap = decodeBitmapFromPath(path)
                    ?: throw IllegalArgumentException("Cannot decode image at $path")
                val pageInfo = PdfDocument.PageInfo.Builder(bitmap.width, bitmap.height, index + 1).create()
                val page = pdfDocument.startPage(pageInfo)
                page.canvas.drawBitmap(bitmap, 0f, 0f, null)
                pdfDocument.finishPage(page)
                bitmap.recycle()
            }

            val fileName = "${outputName}_${UUID.randomUUID()}.pdf"
            val tempFile = File(context.cacheDir, fileName)
            FileOutputStream(tempFile).use { out ->
                pdfDocument.writeTo(out)
            }
            pdfDocument.close()

            val savedPath = saveToDownloads(tempFile, fileName, "application/pdf")
            registerConvertedDocument(File(tempFile.absolutePath), "pdf", ConversionType.IMAGE_TO_PDF.displayName)
            saveConversionHistory(imagePaths.first(), savedPath, ConversionType.IMAGE_TO_PDF)
            savedPath
        }

    suspend fun convertImageFormat(
        imagePath: String,
        targetFormat: Bitmap.CompressFormat,
        quality: Int = 95
    ): String = withContext(Dispatchers.IO) {
        val bitmap = decodeBitmapFromPath(imagePath) ?: throw IllegalArgumentException("Cannot decode image at $imagePath")
        val ext = when (targetFormat) {
            Bitmap.CompressFormat.JPEG -> "jpg"
            Bitmap.CompressFormat.PNG -> "png"
            else -> "webp"
        }
        val fileName = "converted_${UUID.randomUUID()}.$ext"
        val tempFile = File(context.cacheDir, fileName)
        FileOutputStream(tempFile).use { out ->
            bitmap.compress(targetFormat, quality, out)
        }
        bitmap.recycle()

        val type = when (targetFormat) {
            Bitmap.CompressFormat.JPEG -> if (imagePath.endsWith(".png", true)) ConversionType.PNG_TO_JPG else ConversionType.WEBP_TO_JPG
            Bitmap.CompressFormat.PNG -> ConversionType.JPG_TO_PNG
            else -> ConversionType.PNG_TO_JPG
        }
        val mimeType = when (targetFormat) {
            Bitmap.CompressFormat.JPEG -> "image/jpeg"
            Bitmap.CompressFormat.PNG -> "image/png"
            else -> "image/webp"
        }
        val savedPath = saveToDownloads(tempFile, fileName, mimeType)
        registerConvertedDocument(File(tempFile.absolutePath), ext, type.displayName)
        saveConversionHistory(imagePath, savedPath, type)
        savedPath
    }

    suspend fun convertImageToText(imagePath: String): String = withContext(Dispatchers.IO) {
        val parsedUri = Uri.parse(imagePath)
        val uri = if (parsedUri.scheme == null) Uri.fromFile(File(imagePath)) else parsedUri
        val rawText = ocrRepository.extractTextFromUri(uri).text
        if (rawText.isBlank()){
            throw IllegalArgumentException("No text could be found in the selected image. Please try an image with clearer text.")
        }
        val enhancedText = openAiService.processPdfContent(rawText)
        
        val fileName = "ocr_${UUID.randomUUID()}.txt"
        val tempFile = File(context.cacheDir, fileName)
        FileWriter(tempFile).use { writer ->
            writer.write(enhancedText)
        }
        
        val savedPath = saveToDownloads(tempFile, fileName, "text/plain")
        
        // Use a persistent file in internal storage for the database to ensure it's always available
        val internalFile = File(outputDir, fileName)
        FileWriter(internalFile).use { it.write(enhancedText) }
        registerConvertedDocument(internalFile, "txt", ConversionType.IMAGE_TO_TEXT.displayName)
        
        saveConversionHistory(imagePath, savedPath, ConversionType.IMAGE_TO_TEXT)
        savedPath
    }

    suspend fun convertPdfToText(pdfPath: String): String = withContext(Dispatchers.IO) {
        val rawText = try {
            val uri = try { Uri.parse(pdfPath) } catch (e: Exception) { Uri.fromFile(File(pdfPath)) }
            val inputStream = if (uri.scheme == "content") {
                context.contentResolver.openInputStream(uri)
            } else {
                File(pdfPath).inputStream()
            }
            
            inputStream?.use { input ->
                PDDocument.load(input).use { document ->
                    PDFTextStripper().getText(document)
                }
            } ?: ""
        } catch (e: Exception) {
            ""
        }

        if (rawText.isBlank()) {
            throw IllegalArgumentException("No text could be extracted from this PDF. It might be an image-only PDF or scanned document without OCR.")
        }

        val processedText = openAiService.processPdfContent(rawText)

        val fileName = "pdf_text_${UUID.randomUUID()}.txt"
        val tempFile = File(context.cacheDir, fileName)
        FileWriter(tempFile).use { writer ->
            writer.write(processedText)
        }

        val savedPath = saveToDownloads(tempFile, fileName, "text/plain")
        
        val internalFile = File(outputDir, fileName)
        FileWriter(internalFile).use { it.write(processedText) }
        registerConvertedDocument(internalFile, "txt", ConversionType.PDF_TO_TEXT.displayName)
        
        saveConversionHistory(pdfPath, savedPath, ConversionType.PDF_TO_TEXT)
        savedPath
    }

    private suspend fun registerConvertedDocument(file: File, type: String, sourceType: String) {
        val documentEntity = DocumentEntity(
            id = UUID.randomUUID().toString(),
            title = file.name,
            filePath = file.absolutePath,
            thumbnailPath = null,
            fileType = type,
            fileSize = file.length(),
            pageCount = 1,
            sourceType = sourceType,
            createdAt = System.currentTimeMillis(),
            updatedAt = System.currentTimeMillis()
        )
        documentRepository.saveDocument(documentEntity)
    }

    private fun saveToDownloads(
        tempFile: File, 
        displayName: String, 
        mimeType: String,
        subFolder: String? = null
    ): String {
        val resolver = context.contentResolver
        val relativePath = if (subFolder != null) {
            "${StoragePaths.downloadsRelativePath()}/$subFolder"
        } else {
            StoragePaths.downloadsRelativePath()
        }

        val contentValues = ContentValues().apply {
            put(MediaStore.MediaColumns.DISPLAY_NAME, displayName)
            put(MediaStore.MediaColumns.MIME_TYPE, mimeType)
            put(MediaStore.MediaColumns.RELATIVE_PATH, relativePath)
        }

        val uri = resolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, contentValues)
        val finalPath = uri?.let {
            resolver.openOutputStream(it)?.use { output ->
                tempFile.inputStream().use { input ->
                    input.copyTo(output)
                }
            }
            if (subFolder != null) {
                "Download/${StoragePaths.DOWNLOAD_SUBDIR}/$subFolder/$displayName"
            } else {
                StoragePaths.downloadsUserVisiblePath(displayName)
            }
        } ?: tempFile.absolutePath

        return finalPath
    }

    private fun getFileName(path: String): String {
        val uri = Uri.parse(path)
        if (uri.scheme == "content") {
            context.contentResolver.query(uri, null, null, null, null)?.use { cursor ->
                val nameIndex = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME)
                if (cursor.moveToFirst()) {
                    return cursor.getString(nameIndex)
                }
            }
        }
        return File(path).name
    }

    suspend fun resizeImage(imagePath: String, options: ResizeOptions): String =
        withContext(Dispatchers.IO) {
            // Decode original bitmap (supports file paths and content URIs)
            val original = decodeBitmapFromPath(imagePath)
                ?: throw IllegalArgumentException("Cannot decode image at $imagePath")

            // Calculate desired dimensions
            val (newWidth, newHeight) = calculateDimensions(original, options)

            // Convert Bitmap -> Mat
            val srcMat = Mat()
            Utils.bitmapToMat(original, srcMat)

            // Resize using OpenCV
            val dstMat = Mat()
            Imgproc.resize(srcMat, dstMat, Size(newWidth.toDouble(), newHeight.toDouble()), 0.0, 0.0, Imgproc.INTER_AREA)

            // Convert Mat -> Bitmap
            val resized = Bitmap.createBitmap(newWidth, newHeight, Bitmap.Config.ARGB_8888)
            Utils.matToBitmap(dstMat, resized)

            // Determine output format and write file
            val webpFormat = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
                Bitmap.CompressFormat.WEBP_LOSSY
            } else {
                Bitmap.CompressFormat.WEBP
            }

            val format = when (options.outputFormat.lowercase()) {
                "png" -> Bitmap.CompressFormat.PNG
                "webp" -> webpFormat
                else -> Bitmap.CompressFormat.JPEG
            }

            val outputFile = File(outputDir, "resized_${UUID.randomUUID()}.${options.outputFormat}")
            FileOutputStream(outputFile).use { out ->
                resized.compress(format, options.quality, out)
            }

            // Release resources
            srcMat.release()
            dstMat.release()
            original.recycle()
            resized.recycle()

            registerConvertedDocument(outputFile, options.outputFormat, "Resize")
            outputFile.absolutePath
        }

    private fun decodeBitmapFromPath(path: String): Bitmap? {
        // If path points to an actual file, decode directly
        try {
            val file = File(path)
            if (file.exists()) return BitmapFactory.decodeFile(path)

            // Otherwise try treating the string as a Uri (content://... or file://...)
            val uri = try {
                Uri.parse(path)
            } catch (e: Exception) {
                null
            }

            if (uri != null && uri.scheme != null) {
                context.contentResolver.openInputStream(uri)?.use { stream ->
                    return BitmapFactory.decodeStream(stream)
                }
            }
        } catch (e: Exception) {
            // fallthrough to return null
        }
        return null
    }

    private fun calculateDimensions(bitmap: Bitmap, options: ResizeOptions): Pair<Int, Int> {
        return when (options.mode) {
            ResizeMode.WIDTH -> {
                val ratio = options.width.toFloat() / bitmap.width
                val height = if (options.maintainAspectRatio) (bitmap.height * ratio).toInt() else bitmap.height
                options.width to height
            }
            ResizeMode.HEIGHT -> {
                val ratio = options.height.toFloat() / bitmap.height
                val width = if (options.maintainAspectRatio) (bitmap.width * ratio).toInt() else bitmap.width
                width to options.height
            }
            ResizeMode.PERCENTAGE -> {
                val w = (bitmap.width * options.percentage / 100f).toInt()
                val h = (bitmap.height * options.percentage / 100f).toInt()
                w to h
            }
            ResizeMode.CUSTOM -> options.width to options.height
        }
    }

    private suspend fun saveConversionHistory(source: String, output: String, type: ConversionType) {
        conversionHistoryDao.insertConversion(
            ConversionHistoryEntity(
                id = UUID.randomUUID().toString(),
                sourceFile = source,
                outputFile = output,
                conversionType = type.name,
                fileSize = File(output).takeIf { it.exists() }?.length() ?: 0L,
            )
        )
    }
}

package com.ndroid.docmasterai.util

/** Shared download locations for conversions, PDF exports, and resized images. */
object StoragePaths {
    const val DOWNLOAD_SUBDIR = "DocMasterAi"

    // Android's canonical directory name, not the localized UI label "Downloads".
    fun downloadsRelativePath(): String =
        "Download/$DOWNLOAD_SUBDIR"

    fun downloadsUserVisiblePath(fileName: String): String =
        "${downloadsRelativePath()}/$fileName"
}

